    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint64_t aCross = 0; std::uint64_t aScatter = 0;

    std::uint64_t aOrbiterA = 0; std::uint64_t aOrbiterB = 0; std::uint64_t aOrbiterC = 0; std::uint64_t aOrbiterD = 0;
    std::uint64_t aOrbiterE = 0; std::uint64_t aOrbiterF = 0; std::uint64_t aOrbiterG = 0; std::uint64_t aOrbiterH = 0;
    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [kdf-a arx]
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xEAA1DEDF5AC6CFFFULL + 0xAA0AE0E36BDEDFABULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0xC4D33F0911024EB7ULL + 0xD5309A0EC2F051C3ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseA(pNonce * 0xEC42248B044C830BULL + 0x8D61E294331364E0ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseC(pNonce * 0xA2D2F2865B84F8EBULL + 0x8A8917A8500FC2C0ULL);
    const std::uint64_t aNonceWordE = TwistMix64::DiffuseB(pNonce * 0x9B781492C41749BDULL + 0xA8520DA3E7B9B1BCULL);
    const std::uint64_t aNonceWordF = TwistMix64::DiffuseA(pNonce * 0x9690B506A3EF3261ULL + 0xDBEF96962CA91CC8ULL);
    const std::uint64_t aNonceWordG = TwistMix64::DiffuseB(pNonce * 0xC0211AFC48E6CF5BULL + 0xBEA3D11B7F7FB1CDULL);
    const std::uint64_t aNonceWordH = TwistMix64::DiffuseB(pNonce * 0xEE0471E3479FA7C1ULL + 0xAA035138FCA91E13ULL);
