    const std::uint64_t aNonceWordJ = TwistMix64::DiffuseB(pNonce * 0x8F72C78712DF2C3FULL + 0xE01AA197B1C9C1C5ULL);
    const std::uint64_t aNonceWordK = TwistMix64::DiffuseB(pNonce * 0xB4CF0A469409BBDFULL + 0xD22F9F4338FC9728ULL);
    const std::uint64_t aNonceWordL = TwistMix64::DiffuseB(pNonce * 0xAF82AD665C25D56BULL + 0xCBFB30307AC0F051ULL);
    const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xCFED30F6BA521C51ULL + 0x95B86DA2FC987DA3ULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0x9661C15FB8FED147ULL + 0xB8156D3B42290825ULL);
    const std::uint64_t aNonceWordO = TwistMix64::DiffuseC(pNonce * 0xE418CBC269DE8885ULL + 0xE86477C7B1F2F0ECULL);
    const std::uint64_t aNonceWordP = TwistMix64::DiffuseA(pNonce * 0x9BFE171F45C4C0D7ULL + 0xC6A951E1BF8EA34BULL);
    std::uint64_t aDomainWordIngress = pConstants->mIngress;
