            aOrbiterF = ((aWandererB + RotL64(aPrevious, 3U)) + 0xF60E4D017C6FE4FCULL) + aOASaltF[(((511U - aIndex) + 483U)) & S_SALT1];
            aOrbiterC = (aWandererA + RotL64(aCross, 39U)) + 0x76B9BCE20C31CFE0ULL;
            aOrbiterE = (((aWandererG + RotL64(aIngress, 5U)) + RotL64(aCarry, 57U)) + 0x70350A07BD95DA58ULL) + aOASaltC[(((511U - aIndex) + 456U)) & S_SALT1];
            aOrbiterK = ((aWandererK + RotL64(aScatter, 37U)) + 0xF435BC905E0A19C1ULL) + aOASaltD[((aIndex + 131U)) & S_SALT1];
            aOrbiterD = (((aWandererE + RotL64(aPrevious, 14U)) + 0x051621AA5498851CULL) + aOASaltB[((aIndex + 506U)) & S_SALT1]) + aNonceWordG;
            aOrbiterI = (aWandererJ + RotL64(aCross, 43U)) + 0x2CD92C2F05295120ULL;
            aOrbiterH = ((aWandererH + RotL64(aIngress, 51U)) + RotL64(aCarry, 13U)) + 0x6650B3D7CB56485EULL;
            aOrbiterA = ((aWandererF + RotL64(aScatter, 53U)) + 0x54B9D408DA757144ULL) + aOASaltH[((aIndex + 170U)) & S_SALT1];
