            aWandererE = aWandererE + (((RotL64(aIngress, 29U) + aOrbiterI) + RotL64(aOrbiterJ, 41U)) + RotL64(aCarry, 57U));
            aWandererH = aWandererH ^ ((((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterA, 44U)) + aNonceWordL) + aWUSaltB[((aIndex + 31U)) & S_SALT1]);
