            aWandererE = aWandererE ^ ((RotL64(aScatter, 23U) + aOrbiterA) + RotL64(aOrbiterD, 11U));
            aWandererC = aWandererC + (((RotL64(aPrevious, 37U) + aOrbiterK) + RotL64(aOrbiterJ, 21U)) + aWUSaltG[((aIndex + 14U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aCross, 19U) + RotL64(aOrbiterF, 27U)) + aOrbiterI);
