            aWandererJ = aWandererJ ^ (((RotL64(aScatter, 29U) + RotL64(aOrbiterH, 19U)) + aOrbiterE) + aWUSaltC[(((511U - aIndex) + 247U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aPrevious, 21U) + aOrbiterG) + RotL64(aOrbiterB, 48U));
            aWandererB = aWandererB ^ ((RotL64(aCross, 35U) + aOrbiterE) + RotL64(aOrbiterA, 43U));
            aWandererD = aWandererD + (((RotL64(aIngress, 60U) + RotL64(aOrbiterJ, 5U)) + aOrbiterC) + aNonceWordP);
            //
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererE, 53U));
