    std::uint64_t aOrbiterI = 0; std::uint64_t aOrbiterJ = 0; std::uint64_t aOrbiterK = 0;

    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSourceLane;
    READ_IN_MUTABLE_PARAMS;
    const std::uint64_t aNonceWordA = TwistMix64::DiffuseC(pNonce * 0xA82EAEA2CADB0007ULL + 0xF2C47048E2F0213DULL);
    const std::uint64_t aNonceWordB = TwistMix64::DiffuseA(pNonce * 0x94BA67DDE941DDBDULL + 0x941267DB393C0424ULL);
    const std::uint64_t aNonceWordC = TwistMix64::DiffuseC(pNonce * 0xF08C536B25D901C1ULL + 0xDF9BC1581D659365ULL);
    const std::uint64_t aNonceWordD = TwistMix64::DiffuseA(pNonce * 0xB8AAB329496604C5ULL + 0xBF7E7C9015D2AE4AULL);
