    const std::uint64_t aNonceWordM = TwistMix64::DiffuseA(pNonce * 0xDF356BCCA16C5BB1ULL + 0x9140E660AF4CC4FAULL);
    const std::uint64_t aNonceWordN = TwistMix64::DiffuseB(pNonce * 0xAB2CB6A051522ABBULL + 0xFFC1646392273070ULL);
