            //
            aCross = (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 419U)) & S_BLOCK1], 35U) ^ RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 5238U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 2259U)) & S_BLOCK1], 13U) ^ RotL64(aFireLaneB[((S_BLOCK1 - aIndex + 192U)) & S_BLOCK1], 26U));
            aCross = TwistMix64::DiffuseA(((aCross ^ aSeedDomainWordCross) ^ aNonceWordL));
            //
