            aOrbiterA = (aWandererG + RotL64(aIngress, 3U)) + 0x7651C23DC1C28811ULL;
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 37U)) + RotL64(aCarry, 51U)) + 0x0DECE98A994E1F59ULL;
            aOrbiterF = (aWandererD + RotL64(aPrevious, 57U)) + 0x094630B33E679121ULL;
            aOrbiterI = ((aWandererE + RotL64(aCross, 43U)) + 0xF6BF7A7D8477879EULL) + aNonceWordJ;
            aOrbiterB = ((aWandererC + RotL64(aIngress, 60U)) + 0x5A95F5E0EE726386ULL) + aNonceWordB;
            aOrbiterK = (((aWandererJ + RotL64(aScatter, 5U)) + RotL64(aCarry, 29U)) + 0x7894DEB6D1985A4EULL) + aNonceWordM;
            aOrbiterC = ((aWandererI + RotL64(aPrevious, 41U)) + 0x0D2C561A61298EA5ULL) + aOASaltA[(((511U - aIndex) + 259U)) & S_SALT1];
