            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x7321207C5019A2E0ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xA669B18EAE0C3C2EULL) ^ aOUSaltD[(((511U - aIndex) + 118U)) & S_SALT1];
