            aWandererK = aWandererK ^ (((RotL64(aCross, 13U) + aOrbiterB) + RotL64(aOrbiterA, 36U)) + RotL64(aCarry, 47U));
            aWandererB = aWandererB + (((RotL64(aIngress, 57U) + RotL64(aOrbiterI, 21U)) + aOrbiterD) + aWUSaltF[((aIndex + 147U)) & S_SALT1]);
            //
